examples.template:
List {
    MonarchInboxRow(
        {{rows.0.title}},
        preview: {{rows.0.preview}},
        timestamp: {{rows.0.timestamp|date}},
        now: {{now|date}},
        avatarName: {{rows.0.title}},
        systemImage: "tray",
        systemImageLabel: {{iconLabel}},
        isCurrent: {{rows.0.id}} == {{current}}
    ) {
        MonarchBadge({{rows.0.status}}, tone: {{rows.0.tone|tone}})
    } trailing: {
        HStack(spacing: 8) {
            Text("#" + {{rows.0.id}}).monarchTextStyle(.caption)
            MonarchAvatar(image: nil, name: {{assignee}}, size: .xs)
        }
    }
    .listRowBackground(Color.clear)
    MonarchInboxRow(
        {{rows.1.title}},
        preview: {{rows.1.preview}},
        timestamp: {{rows.1.timestamp|date}},
        now: {{now|date}},
        avatarName: {{rows.1.title}},
        systemImage: "tray",
        systemImageLabel: {{iconLabel}},
        isCurrent: {{rows.1.id}} == {{current}}
    ) {
        MonarchBadge({{rows.1.status}}, tone: {{rows.1.tone|tone}})
    } trailing: {
        HStack(spacing: 8) {
            Text("#" + {{rows.1.id}}).monarchTextStyle(.caption)
            MonarchAvatar(image: nil, name: {{assignee}}, size: .xs)
        }
    }
    .listRowBackground(Color.clear)
    MonarchInboxRow(
        {{rows.2.title}},
        preview: {{rows.2.preview}},
        timestamp: {{rows.2.timestamp|date}},
        now: {{now|date}},
        avatarName: {{rows.2.title}},
        systemImage: "tray",
        systemImageLabel: {{iconLabel}},
        isCurrent: {{rows.2.id}} == {{current}}
    ) {
        MonarchBadge({{rows.2.status}}, tone: {{rows.2.tone|tone}})
    } trailing: {
        HStack(spacing: 8) {
            Text("#" + {{rows.2.id}}).monarchTextStyle(.caption)
            MonarchAvatar(image: nil, name: {{assignee}}, size: .xs)
        }
    }
    .listRowBackground(Color.clear)
}
.listStyle(.plain)
.monarchCanvas()
.accessibilityLabel({{label}})

