List {
    MonarchInboxRow(
        "Jordan Kim",
        preview: "Can I change the delivery address on my order?",
        timestamp: Date(timeIntervalSince1970: 1_778_414_100),
        now: Date(timeIntervalSince1970: 1_778_414_400),
        avatarName: "Jordan Kim",
        systemImage: "tray",
        systemImageLabel: "via email",
        isCurrent: "41" == "41"
